{
 "summary": "The file states four results. (1) The centered simplex (n+1)Δn − (1,…,1) has barycenter 0. (2) For n > 0 its volume is (n+1)^n/n!. (3) For n > 0 there is a compact convex full-dimensional body with barycenter 0 whose only interior lattice point is 0 and whose volume equals (n+1)^n/n!. (4) Every such body has volume strictly less than (n+1)^n/n!. The most important caveat: the main theorem uses a strict inequality `<`, while the paper proves `≤` and says the bound is sharp. Theorem (4) is false, and it directly contradicts theorem (3) as stated in the same file.",
 "glossary": [
  {"decl": "Ehrhart.Space", "line": 10, "plain": "ℝ^n modelled as Fin n → ℝ, with sup-norm topology and product Lebesgue measure", "standard_concept": "Euclidean space ℝ^n", "matches_standard": "yes", "note": "Same topology and Lebesgue measure as Euclidean ℝ^n."},
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "Δn = {x : x_i ≥ 0, Σ x_i ≤ 1}", "standard_concept": "conv{0, e1, …, en}", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "(n+1)Δn − (1,…,1)", "standard_concept": "centered simplex from the paper", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "Lebesgue volume of K, as a real number (∞ is sent to 0)", "standard_concept": "vol(K)", "matches_standard": "yes", "note": "Finite for compact K, so the ∞ ↦ 0 convention never applies here."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "vol(K)^{-1} ∫_K x dx", "standard_concept": "barycenter", "matches_standard": "yes", "note": "For compact K with nonempty interior, the volume is positive and the integral converges."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "the set of z ∈ ℤ^n with z ∈ int K", "standard_concept": "int(K) ∩ ℤ^n", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "a convex compact set with nonempty interior, barycenter 0, and int K ∩ ℤ^n = {0}", "standard_concept": "hypotheses of Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+1)^n/n!", "standard_concept": "Ehrhart bound", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For all n, the barycenter of (n+1)Δn − 1 is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n > 0, vol((n+1)Δn − 1) = (n+1)^n/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n > 0, there exists a convex compact full-dimensional K with barycenter 0, int K ∩ ℤ^n = {0}, and vol K = (n+1)^n/n!."},
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n > 0, every convex compact S with nonempty interior, barycenter 0, and int S ∩ ℤ^n = {0} satisfies vol S < (n+1)^n/n! (strict inequality)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "If K is a full-dimensional compact convex body with barycenter 0 and int K ∩ ℤ^n = {0}, then vol K ≤ (n+1)^n/n!."},
  {"ref": "Sharpness remark after Theorem 1.1", "plain": "The simplex (n+1)Δn − (1,…,1) has barycenter 0, has no other interior lattice point, and has volume (n+1)^n/n!."}
 ],
